UPDATE task
title = #{title}, description = #{description}, type = #{type}, warning_history_id = #{warningHistoryId}, gas_type = #{gasType}, assignee_type = #{assigneeType}, car_id = #{carId}, employee_id = #{employeeId}, x = #{x}, y = #{y}, area_name = #{areaName}, assigned_time = #{assignedTime}, accepted_time = #{acceptedTime}, checkin_time = #{checkinTime}, checkin_x = #{checkinX}, checkin_y = #{checkinY}, checkin_photo_base64 = #{checkinPhotoBase64}, yolo_person_count = #{yoloPersonCount}, checkin_remark = #{checkinRemark}, review_result = #{reviewResult}, review_remark = #{reviewRemark}, review_time = #{reviewTime}, reviewer_user_id = #{reviewerUserId}, warning_resolved = #{warningResolved},
