mapper.select:
SELECT 
FROM task

    AND status = #{status}
    AND assignee_type = #{assigneeType}
    AND car_id = #{carId}
    AND employee_id = #{employeeId}
    AND warning_history_id = #{warningHistoryId}
    AND (title LIKE CONCAT('%', #{keyword}, '%') OR area_name LIKE CONCAT('%', #{keyword}, '%'))

ORDER BY created_at DESC, id DESC

SELECT 
FROM task

    AND assignee_type = #{assigneeType}
    AND employee_id = #{employeeId}
    AND car_id = #{carId}
    AND 1 = 0

ORDER BY created_at DESC, id DESC
